                println!("Loading expected: {}", out_file);
                let mut out_json = load_event_file(out_file)?;

                out_json.reverse();

                let mut results = Vec::new();
                for (id, mut json) in in_json.into_iter().enumerate() {
                    let uri = EventOriginUri{
                        host: "test".into(),
