                    if let Some(expected) = out_json.pop() {
                        assert_eq!(sorted_serialize(&value)?, sorted_serialize(&expected)?, "Input event #{} Expected `{}`, but got `{}`", i, sorted_serialize(&expected)?, sorted_serialize(&value)?);
                    }
                }
                Ok(())
            }
        )*
    };
